/**
 * How Yongle coin (`eiraku-sen`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/eiraku-sen";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"A coin in a thin ring: two thin square frames round the hole, one inside the other, each 2 wide, and the four characters 永楽通寳 round it, 永 above, 寳 to the left, 通 to the right and 樂 below, in the brush hand of the 1892 crest book. The ring is struck first, then the squares, each frame being the space between four long ruled lines and four more; each character is the outline of its strokes in arcs of struck circles and ruled lines.","ja":"細い輪の中に銭を置きます。穴のまわりに、幅2の細い四角い枠を二重に作り、そのまわりに「永楽通寳」の四文字を、上に永、左に寳、右に通、下に樂と並べます。文字は1892年の紋帳の筆の書き方です。先に輪を描き、次に四角を描きます。四角の枠は、長い直線四本と、さらに四本の間のすき間です。文字は、筆の線の輪郭を、描いた円の弧と直線で囲んだものです。"};

export default construction;
export { construction, description };
